// PresenceHub data loader.
// Served over http(s): fetches data/*.json (same origin).
// Opened via file:// (or fetch fails): falls back to js/data.bundle.js (window.__DATA__),
// regenerated by `node tools/build-data-bundle.mjs`.
(function () {
  'use strict';

  var FILES = {
    meta: 'meta.json',
    employees: 'employees.json',
    departments: 'departments.json',
    hourly: 'hourly.json',
    activities: 'activities.json',
    timeline: 'timeline.json',
    appUsage: 'app-usage.json',
    attendanceHistory: 'attendance-history.json',
    notifications: 'notifications.json',
    scores: 'scores.json',
  };

  function fetchJson(file) {
    return fetch('data/' + file, { credentials: 'same-origin', cache: 'no-cache' }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status + ' for ' + file);
      return r.json();
    });
  }

  function loadBundle() {
    if (window.__DATA__) return Promise.resolve(window.__DATA__);
    return new Promise(function (resolve, reject) {
      var s = document.createElement('script');
      s.src = 'js/data.bundle.js';
      s.onload = function () { window.__DATA__ ? resolve(window.__DATA__) : reject(new Error('Bundle did not define data')); };
      s.onerror = function () { reject(new Error('Could not load js/data.bundle.js')); };
      document.head.appendChild(s);
    });
  }

  function validate(d) {
    var ok = d && d.meta && Array.isArray(d.employees) && Array.isArray(d.departments) &&
      d.hourly && Array.isArray(d.activities) && d.timeline && d.appUsage &&
      d.attendanceHistory && Array.isArray(d.notifications) && d.scores;
    if (!ok) throw new Error('Mock data is incomplete');
    return d;
  }

  var cached = null;
  function load() {
    if (cached) return cached;
    var keys = Object.keys(FILES);
    var viaFetch = location.protocol === 'file:'
      ? Promise.reject(new Error('file:// — using bundle'))
      : Promise.all(keys.map(function (k) { return fetchJson(FILES[k]); })).then(function (vals) {
        var out = {};
        keys.forEach(function (k, i) { out[k] = vals[i]; });
        return out;
      });
    cached = viaFetch
      .catch(function () { return loadBundle(); })
      .then(validate);
    return cached;
  }

  window.PH_DATA = Object.freeze({ load: load });
})();
